package org.racedaydreams.domain.strength;
import java.util.*;

/** Curated original artwork identifiers, independent of Android resources. No generic fallback. */
public final class TechniqueIllustrations {
    private TechniqueIllustrations() {}
    public record Artwork(String asset,String description,List<String> phases) {
        public Artwork {
            if(asset==null||!asset.matches("guide_[a-z_]+")||description==null||description.trim().isEmpty()||phases==null||phases.isEmpty())throw new IllegalArgumentException("Incomplete instructional art");
            phases=Collections.unmodifiableList(new ArrayList<>(phases));
        }
    }
    public static Artwork forExercise(String id) {return switch(id) {
        case "dead-hang" -> new Artwork("guide_dead_hang","Dead hang: both hands grip a secure overhead bar, arms extended and shoulders controlled. Feet are off the floor with knees gently bent. Breathe steadily without swinging; use a stable step to reach or leave the bar safely.",Arrays.asList("Secure grip; controlled hang"));
        case "seated-leg-curl" -> new Artwork("guide_seated_leg_curl","Seated leg curl: thighs are secured beneath the upper restraint, back supported and knee near the machine pivot. With legs extended, the lower calves rest on the roller below them. Bend the knees to pull the roller down and back beneath the seat, then extend under control.",Arrays.asList("Calves on lower roller; thighs secured","Bend knees; return smoothly"));
        case "incline-dumbbell-press" -> new Artwork("guide_incline_dumbbell_press","Incline dumbbell press: sit back against a moderately inclined bench with feet planted and weights beside the upper chest. Press the dumbbells above the upper chest, then lower smoothly without arching off the backrest.",Arrays.asList("Back supported; weights by chest","Press; controlled return"));
        case "dumbbell-curl" -> new Artwork("guide_dumbbell_curl","Dumbbell curl: stand with palms facing forwards and arms beside the trunk. Bend both elbows to lift the weights toward the shoulders, then lower smoothly without rocking or moving the upper arms forwards.",Arrays.asList("Palms forward; elbows by sides","Curl; lower without swinging"));
        case "ez-bar-curl" -> new Artwork("guide_ez_bar_curl","EZ-bar curl: grip the angled sections of the bar with palms turned upwards and upper arms alongside the trunk. Bend the elbows to lift the bar, then lower smoothly without leaning backwards.",Arrays.asList("Comfortable angled grip","Curl; controlled return"));
        case "leg-extension" -> new Artwork("guide_leg_extension","Leg extension: sit with back supported and knees aligned near the machine pivot; the roller rests in front of lower shins above the ankles. Extend the knees to lift it, then lower without kicking or lifting the hips.",Arrays.asList("Pad in front of shins","Extend knees; lower slowly"));
        case "suitcase-carry" -> new Artwork("guide_suitcase_carry","Suitcase carry: hold one dumbbell at the side with the opposite hand empty. Walk with controlled steps while shoulders remain level and trunk steady, then set the load down safely and change sides.",Arrays.asList("One load; shoulders level","Walk steadily; change sides"));
        case "weighted-plank" -> new Artwork("guide_weighted_plank","Weighted forearm plank: forearms and toes support the body with elbows beneath shoulders and a small flat plate securely positioned over the mid-back. Keep a controlled line and breathe. Get help to place and remove the load; choose an unloaded hold if it cannot be secured.",Arrays.asList("Secure small load; hold and breathe"));
        case "pallof-press" -> new Artwork("guide_pallof_press","Pallof press: stand with a chest-height cable coming from the side and hold the handle at the sternum in both hands. Extend the hands straight forward while resisting rotation; return to the chest. Keep the same forward trunk direction, then train the other side.",Arrays.asList("Handle at chest; cable from side","Press forwards; resist rotation"));
        case "ab-wheel" -> new Artwork("guide_ab_wheel","Kneeling ab-wheel rollout: begin on a mat with both hands gripping the wheel axle beneath shoulders. Roll forwards a manageable distance while keeping knees supported and trunk controlled, then return without sagging the back.",Arrays.asList("Kneel; wheel beneath shoulders","Roll forward; return under control"));
        case "triceps-pressdown" -> new Artwork("guide_triceps_pressdown","Triceps pressdown: face a high cable pulley holding the short bar with elbows beside the ribs. From bent elbows, extend the forearms down until arms are comfortably straight, then return slowly while keeping upper arms still.",Arrays.asList("Elbows beside ribs; bar raised","Extend down; controlled return"));

        case "goblet-squat" -> new Artwork("guide_goblet_squat","Goblet squat: hold one dumbbell vertically against the chest with both hands. From standing, bend hips and knees into a controlled squat with feet flat; return to standing without losing the close hold.",Arrays.asList("Hold at chest; brace","Squat; stand under control"));
        case "dumbbell-row" -> new Artwork("guide_dumbbell_row","One-arm dumbbell row: support one hand and knee on a stable bench with the opposite foot on the floor. Let the weighted arm hang, then draw its elbow toward the hip and return without twisting the trunk. Repeat on the other side.",Arrays.asList("Support on bench; arm extended","Pull toward hip; lower"));
        case "push-up" -> new Artwork("guide_push_up","Push-up: top frame shows hands beneath shoulders, straight arms and supported toes with trunk aligned. Bottom frame shows chest lowered near the mat with elbows bent, while shoulders, hips and ankles stay in a controlled line. Press back up.",Arrays.asList("Straight arms; steady body","Lower chest; press back up"));
        case "barbell-curl" -> new Artwork("guide_barbell_curl","Barbell curl: stand holding a straight bar with palms upwards and elbows beside the trunk. Bend the elbows to raise the bar toward the chest, then lower without swinging the hips or leaning backwards.",Arrays.asList("Underhand grip; arms down","Bend elbows; lower slowly"));
        case "hammer-curl" -> new Artwork("guide_hammer_curl","Hammer curl: hold two dumbbells beside the thighs with palms facing inward. Bend the elbows while retaining the neutral grip, then lower smoothly without rocking the trunk.",Arrays.asList("Neutral grip; elbows by sides","Curl; controlled return"));
        case "lateral-raise" -> new Artwork("guide_lateral_raise","Dumbbell lateral raise: stand holding weights beside the thighs, then raise the arms outward to about shoulder height with softly bent elbows. Lower under control without heaving or shrugging the weights.",Arrays.asList("Weights beside thighs","Raise outward; lower smoothly"));
        case "dead-bug" -> new Artwork("guide_dead_bug","Dead bug: top frame shows lying on a mat with arms raised and knees bent above hips. Bottom frame shows an opposite arm and leg extended while the other arm and knee stay raised. Return and alternate sides, shortening the reach if the trunk moves.",Arrays.asList("Arms up; knees over hips","Opposite arm and leg reach"));
        case "bird-dog" -> new Artwork("guide_bird_dog","Bird dog: begin on hands and knees with hands under shoulders and knees under hips. Extend the opposite arm and leg into a long line, keeping pelvis level. Return to all fours and alternate without arching the back.",Arrays.asList("Hands and knees supported","Reach opposite arm and leg"));
        case "seated-calf-raise" -> new Artwork("guide_seated_calf_raise","Seated machine calf raise: sit with knees bent and thigh pad secured above the knees; forefeet rest on the raised footplate. Lower heels comfortably, then raise them to lift the resistance without bouncing.",Arrays.asList("Forefeet on plate; thighs secured","Raise heels; return slowly"));

        case "leg-press" -> new Artwork("guide_leg_press","Leg press: sit with back and pelvis against the machine pads and both feet flat on the platform. Lower by bending hips and knees only as far as you can keep the pelvis supported, then press without snapping the knees straight. Use the machine safeties.",Arrays.asList("Back supported; bend under control","Press; avoid locking knees"));
        case "dumbbell-shoulder-press" -> new Artwork("guide_dumbbell_shoulder_press","Seated dumbbell shoulder press: sit against an upright bench with feet planted and a dumbbell beside each shoulder. Press the weights above the shoulders, then lower smoothly, keeping ribs controlled and wrists beneath the weights.",Arrays.asList("Feet planted; weights at shoulders","Press overhead; return smoothly"));
        case "lat-pulldown" -> new Artwork("guide_lat_pulldown","Lat pulldown: sit with thighs secured beneath the pads and hold the overhead bar with a comfortable overhand grip. Pull toward the upper chest in front of the face with elbows moving down, then return overhead without rocking the trunk.",Arrays.asList("Thighs secured; arms overhead","Pull in front to upper chest"));
        case "front-squat" -> new Artwork("guide_front_squat","Front squat: support the bar across the front of the shoulders with elbows pointing forwards and hands steadying it. Stand braced, then bend hips and knees together, keeping heels planted and torso controlled; stand without allowing the bar to roll.",Arrays.asList("Front rack; elbows forwards","Lower with control; stand"));
        case "reverse-lunge" -> new Artwork("guide_reverse_lunge","Dumbbell reverse lunge: stand holding a manageable dumbbell beside each hip. Step one foot backwards, bend both knees with front foot flat and trunk steady, then drive through the front leg to return. Alternate sides if prescribed.",Arrays.asList("Stand; loads at sides","Step back; lower and return"));
        case "step-up" -> new Artwork("guide_step_up","Dumbbell step-up: place the whole working foot on a stable low step while holding dumbbells at the sides. Stand through that leg without jumping from the floor; the trailing knee may rise for balance. Lower under control before changing sides.",Arrays.asList("Whole foot on a stable step","Stand through the working leg"));
        case "calf-raise" -> new Artwork("guide_machine_calf_raise","Standing machine calf raise: adjust the shoulder pads, stand with forefeet supported on the machine platform and hold the handles for balance. With knees softly extended, raise the heels and lower slowly through a comfortable ankle range without bouncing.",Arrays.asList("Set shoulder pads; heels down","Raise heels; lower slowly"));
        case "standing-calf-raise" -> new Artwork("guide_machine_calf_raise","Standing machine calf raise: adjust the shoulder pads, support the forefeet on the footplate and steady yourself on the handles. Lift both heels without bending the knees to propel the load, then lower slowly within a comfortable range.",Arrays.asList("Forefeet supported; steady trunk","Lift heels; controlled return"));
        case "side-plank" -> new Artwork("guide_side_plank","Side plank: support on one forearm with elbow directly below shoulder and feet stacked. Lift the hips so shoulder, hip and ankle form a steady line; keep breathing and lower to finish. Repeat on the other side as prescribed.",Arrays.asList("Elbow under shoulder; hips lifted"));
        case "farmers-carry" -> new Artwork("guide_farmers_carry","Farmer\u2019s carry: hold a manageable dumbbell in each hand beside the hips, stand tall and walk with controlled steps. Keep shoulders level without swinging the weights. Set them down deliberately; record whether the entered load is per hand.",Arrays.asList("Stand tall; loads at sides","Walk steadily; set down safely"));
        case "lying-leg-curl" -> new Artwork("guide_lying_leg_curl","Lying leg curl: lie face down on the machine with knees near the pivot and ankle pad just above the heels. Keep hips supported as the knees bend to lift the pad, then extend slowly without swinging the legs.",Arrays.asList("Align knee pivot; hips supported","Curl the pad; lower smoothly"));
        case "kettlebell-swing" -> new Artwork("guide_kettlebell_swing","Two-handed kettlebell swing: hinge with the bell passing back between the legs, then extend hips to float the bell to around chest height with relaxed arms. Keep feet planted and ribs controlled; return to a hinge as the bell falls. This is not an overhead swing.",Arrays.asList("Hinge; bell travels behind","Extend hips; bell floats forward"));

        case "hip-thrust" -> new Artwork("guide_hip_thrust","Barbell hip thrust: support the upper back on a stable bench, plant both feet and steady a padded bar across the hip crease. Lift the hips until the torso and thighs are near level, keeping ribs controlled; lower the hips without sliding off the bench or overarching the back.",Arrays.asList("Stable bench; padded bar","Lift hips; lower under control"));
        case "trap-bar-deadlift" -> new Artwork("guide_trap_bar_deadlift","Trap-bar deadlift: stand inside the hexagonal frame with feet planted and grip the side handles. Start with hips back, knees bent and a braced trunk; extend hips and knees together to stand tall without leaning back, then lower the bar under control.",Arrays.asList("Brace inside the frame","Stand tall; lower smoothly"));
        case "barbell-row" -> new Artwork("guide_barbell_row","Barbell row: hinge forward with softly bent knees, hips back and a steady neutral trunk. Begin with arms extended below the shoulders, pull the bar toward the lower ribs with elbows travelling behind, then lower without standing up or rocking.",Arrays.asList("Hinge; arms extended","Pull to lower ribs; return"));
        case "pull-up" -> new Artwork("guide_pull_up","Overhand pull-up: grip a secure overhead bar and begin in a controlled hang. Pull upward until the chin comfortably clears the bar, then lower smoothly. Keep legs controlled without swinging or using a kick.",Arrays.asList("Controlled hang","Pull; lower without swinging"));
        case "dumbbell-bench-press" -> new Artwork("guide_dumbbell_bench_press","Dumbbell bench press: lie supported on a flat bench with feet planted and a separate dumbbell in each hand. Begin with bent elbows and weights beside the chest, press above the chest, then lower under control with forearms beneath the weights.",Arrays.asList("Lower beside the chest","Press above the chest"));
        case "deadlift" -> new Artwork("guide_deadlift","Conventional deadlift: start with bar on the floor close to the shins, hips back, knees bent, arms straight and hands outside the legs. Stand by extending hips and knees together while the bar stays close, finish tall without leaning back, then lower under control.",Arrays.asList("Brace; bar close to shins","Stand tall; lower under control"));
        case "overhead-press" -> new Artwork("guide_overhead_press","Standing barbell overhead press: begin with the bar at shoulder level and a braced upright trunk. Press the bar above the shoulders with feet planted and no leg drive, then lower under control without leaning back.",Arrays.asList("Brace; bar at shoulders","Press overhead; return"));
        case "seated-cable-row" -> new Artwork("guide_seated_cable_row","Seated cable row: sit with feet supported and knees softly bent, hold the low cable handle with arms extended, then pull toward the lower ribs with elbows close and a steady trunk. Return the handle under control without rocking backwards.",Arrays.asList("Arms extended; feet supported","Pull to lower ribs; return"));
        case "back-squat" -> new Artwork("guide_back_squat","Back squat: stand with the bar supported across the upper back and both hands gripping it; lower hips and knees together with feet flat and a controlled trunk, then stand. Use suitable rack safeties or a spotter.",Arrays.asList("Brace; bar on upper back","Lower under control; stand"));
        case "split-squat" -> new Artwork("guide_bulgarian_split_squat","Bulgarian split squat: rear foot rests on a stable low bench, front foot flat with space to bend the knee; lower through the front leg with the knee following the toes, then rise without pushing off the bench. Bodyweight movement shown; optional loads are not illustrated.",Arrays.asList("Stable rear support","Lower through the front leg"));
        case "plank" -> new Artwork("guide_plank","Forearm plank: prepare with forearms supported and elbows under shoulders; lift knees and support on forearms and toes with shoulders, hips and ankles aligned, breathing steadily. Lower knees to end the hold.",Arrays.asList("Prepare on forearms","Lift and hold; breathe"));
        case "romanian-deadlift" -> new Artwork("guide_romanian_deadlift","Romanian deadlift: standing with the bar close to the thighs; then hips move backwards with softly bent knees, a neutral back and the bar close to the shins.",Arrays.asList("Stand tall","Hinge at the hips"));
        case "glute-bridge" -> new Artwork("guide_glute_bridge","Bodyweight glute bridge: begin lying on a mat with bent knees and flat feet; then lift the hips while the shoulders remain supported, keeping ribs controlled.",Arrays.asList("Feet flat; knees bent","Lift hips under control"));
        case "bench-press" -> new Artwork("guide_bench_press","Bench press: lie supported with feet planted, lower the bar over the chest with bent elbows, then press above the chest with arms extended.",Arrays.asList("Controlled lowering","Press above the chest"));
        case "walking-lunge" -> new Artwork("guide_walking_lunge","Walking lunge: begin standing; step forward and bend both knees with the front foot flat, torso upright and back knee lowered under control.",Arrays.asList("Stand tall","Step and lower"));
        default -> CatalogueTechniqueIllustrations.forExercise(id);
    };}
    public static Artwork forRoutine(String id) {return switch(id) {
        case "lunge" -> forExercise("walking-lunge");
        case "bridge" -> forExercise("glute-bridge");
        case "swing" -> new Artwork("guide_leg_swings","Supported leg swings: hold a stable rail, move one leg gently forward and back while the other foot stays planted and trunk stays upright.",Arrays.asList("Swing gently forward","Return gently behind"));
        case "walk","jog" -> new Artwork("guide_walk","Easy walking option: use a comfortable stride, upright relaxed posture and natural arm movement. An easy jog is optional if comfortable.",Arrays.asList("Walk comfortably"));
        case "march" -> new Artwork("guide_march","Controlled marching: stand tall, then lift one knee comfortably with the opposite arm; lower and alternate sides without leaning back.",Arrays.asList("Stand tall","Lift; lower and alternate"));
        case "calf" -> new Artwork("guide_calf_raise","Supported calf raises: hold a stable rail, start with heels down, then lift both heels gently onto the forefoot and lower under control.",Arrays.asList("Heels down","Rise and lower slowly"));
        case "hip" -> new Artwork("guide_hip_flexor","Hip-flexor stretch: half-kneel on a mat with the front foot flat, keep the trunk upright and gently move the pelvis forward without arching the back.",Arrays.asList("Half-kneel; gentle forward shift"));
        case "quad" -> new Artwork("guide_quad_stretch","Supported quad stretch: hold a stable rail, bend the other knee and gently support the ankle behind you, keeping balance and avoiding force.",Arrays.asList("Stand supported; hold gently"));
        case "glute" -> new Artwork("guide_seated_glute","Seated glute stretch: sit on a stable chair with one foot flat, rest the other ankle across the opposite thigh and hinge forward gently without forcing the knee down.",Arrays.asList("Sit securely; gentle stretch"));
        case "stride" -> new Artwork("guide_strides","Controlled strides: build gradually into relaxed brisk running with smooth steps and arm movement, then ease down and walk to recover. Not maximal sprinting.",Arrays.asList("Build smoothly","Relax and ease down"));
        case "circles" -> new Artwork("guide_ankle_circles","Ankle circles: hold a stable rail, lift one foot slightly and rotate the ankle slowly while the supporting leg and trunk stay steady.",Arrays.asList("Supported gentle ankle rotation"));
        case "calf-stretch" -> new Artwork("guide_calf_stretch","Calf stretch: hold a stable wall, front knee softly bent and back leg comfortable with the whole back foot including heel down; lean gently without bouncing.",Arrays.asList("Back heel down; gentle stretch"));
        case "ankle" -> new Artwork("guide_ankle_rocks","Ankle rocks: half-kneeling with the front foot flat, move the front knee gently forward over the toes while keeping the heel down.",Arrays.asList("Half-kneeling","Rock gently; heel down"));
        default -> null;
    };}
}
